    const day = (n, hh) => Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + n, hh) - KST;
    if (h < OPEN) { t = day(0, OPEN); continue; }
    if (h >= CLOSE) { t = day(1, OPEN); continue; }
    const step = Math.min(left, day(0, CLOSE) - t);
    t += step; left -= step;
  }
