  out.sms.push({ phone: e164(p.phone), text: ASK(p.asked.map((di) => r.days[di].date)) });
}
// 그날 이 사람을 넣어도 예산 안인가 — 이 사람 + 남은 자리를 남은 후보 중 가장 싼 사람들로 채워도 넘지 않게
